using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PurifyEffectAmountCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/PurifyEffectAmountCustomDescription", order = 0)]
public class PurifyEffectAmountCustomDescription : PurifyCorruptWithMultiplierCustomDescription
{
	private const string effectYouHaveThenDecreaseEffectID = "EffectYouHaveThenDecreaseEffect";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		PurifyEffectAmountAction purifyEffectAmountAction = battleAction as PurifyEffectAmountAction;
		string text = "";
		if (purifyEffectAmountAction.GainEffect)
		{
			text = purifyEffectAmountAction.GainEffectAction.GetActionDescription(purifyEffectAmountAction.GainEffectAmount) + "\n";
		}
		if (purifyEffectAmountAction.SpendEffect && (LanguagesIndexes.IsCurrentLanguageJapanese() || LanguagesIndexes.IsCurrentLanguageSimplifiedChinese() || LanguagesIndexes.IsCurrentLanguageTraditionalChinese() || LanguagesIndexes.IsCurrentLanguageKorean()))
		{
			string purifyMultiplierString = GetPurifyMultiplierString(amountModified, purifyEffectAmountAction);
			string arg = purifyEffectAmountAction.PurifyCorruptAction.GetActionDescription(GetAmountWithoutEquation(purifyMultiplierString), GetBonusAmountWithoutEquation(purifyMultiplierString)).RemoveLast();
			return text + Smart.Format(base.localizationManager.GetLocalizedString("EffectYouHaveThenDecreaseEffect"), purifyEffectAmountAction.Effect.GetEffectName(), arg, ThenDecreaseEffect(purifyEffectAmountAction));
		}
		return text + base.GetActionDescription(amountModified, battleAction);
	}

	protected override string GetRawLocalizedDescription(BattleAction battleAction)
	{
		PurifyEffectAmountAction purifyEffectAmountAction = battleAction as PurifyEffectAmountAction;
		return Smart.Format(purifyEffectAmountAction.SpendEffect ? base.localizationManager.GetLocalizedString("EffectYouHaveThenDecreaseEffect") : base.localizationManager.GetLocalizedEffectYouHave(), purifyEffectAmountAction.Effect.GetEffectName(), ThenDecreaseEffect(purifyEffectAmountAction));
	}

	private string ThenDecreaseEffect(PurifyEffectAmountAction purifyEffectAmountAction)
	{
		return base.localizationManager.GetLocalizedThenDecreaseEffect(purifyEffectAmountAction.Effect, purifyEffectAmountAction.SpendEffectAmount);
	}
}
